#include <stdlib.h>

static char buf[1 << 20];
static int buf_pos = 0, buf_len = 0;

static inline int nextChar(void) {
    if (buf_pos >= buf_len) {
        buf_len = fread(buf, 1, sizeof(buf), stdin);
        buf_pos = 0;
        if (buf_len == 0) return EOF;
    }
    return buf[buf_pos++];
}

static int readInt(void) {
    int c = nextChar();
    while (c <= ' ' && c != EOF) c = nextChar();

    int sign = 1;
    if (c == '-') {
        sign = -1;
        c = nextChar();
    }

    int num = 0;
    while (c > ' ') {
        num = num * 10 + (c - '0');
        c = nextChar();
    }
    return num * sign;
}

